begin;
do $$ declare au uuid:=gen_random_uuid();pu uuid:=gen_random_uuid();su uuid:=gen_random_uuid();ap uuid:=gen_random_uuid();pp uuid:=gen_random_uuid();sp uuid:=gen_random_uuid();neutral uuid;job uuid;e uuid;t date:=(now() at time zone 'America/Sao_Paulo')::date;begin
 insert into auth.users(id,email) values(au,'qa-delete-admin-'||au||'@example.invalid'),(pu,'qa-delete-patient-'||pu||'@example.invalid'),(su,'qa-delete-staff-'||su||'@example.invalid');
 insert into public.profiles(id,user_id,username,full_name,role) values(ap,au,'qa-'||au,'QA deletion admin','admin'),(pp,pu,'qa-'||pu,'QA deletion patient','patient'),(sp,su,'qa-'||su,'QA deletion secretary','secretary');
 insert into public.staff_permissions(user_id,view_crm,manage_clients) values(su,true,true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',au,'role','authenticated','aal','aal1')::text,true);execute 'set local role authenticated';
 neutral:=public.crm_save_client(null,'QA neutral deletion','21999001122');
 begin perform public.crm_delete_client(neutral,'QA neutral deletion',false);raise exception 'FAIL deleted without confirmation';exception when raise_exception then if sqlerrm like 'FAIL%' then raise;end if;end;
 begin perform public.crm_delete_client(neutral,'Wrong customer',true);raise exception 'FAIL wrong client name';exception when raise_exception then if sqlerrm like 'FAIL%' then raise;end if;end;
 begin perform public.crm_delete_client(ap,'QA deletion admin',true);raise exception 'FAIL admin profile deleted';exception when raise_exception then if sqlerrm like 'FAIL%' then raise;end if;end;
 job:=public.crm_delete_client(neutral,'QA neutral deletion',true);
 if exists(select 1 from public.profiles where id=neutral) or not exists(select 1 from public.client_deletion_jobs where id=job and user_id is null and files='[]') then raise exception 'FAIL neutral deletion';end if;
 e:=public.crm_save_enrollment(null,pp,'journey',t,t+90,false,1,'QA observations','active',70,170);
 perform public.admin_correct_water(pp,t,500,'QA deletion fixture');
 insert into public.care_tasks(patient_id,title,created_by) values(pp,'QA task',ap);
 insert into public.staff_tasks(patient_id,title,created_by) values(pp,'QA staff task',ap);
 begin perform public.crm_delete_client(pp,'QA deletion patient',true);raise exception 'FAIL active period no acknowledgement';exception when raise_exception then if sqlerrm like 'FAIL%' then raise;end if;end;
 begin perform public.crm_delete_client(pp,'QA deletion patient',true,true,'wrong');raise exception 'FAIL active period no typed confirmation';exception when raise_exception then if sqlerrm like 'FAIL%' then raise;end if;end;
 begin perform public.crm_delete_client(pp,'QA deletion patient',true,true,null);raise exception 'FAIL active period null confirmation';exception when raise_exception then if sqlerrm like 'FAIL%' then raise;end if;end;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',su,'role','authenticated','aal','aal1')::text,true);
 begin perform public.crm_delete_client(pp,'QA deletion patient',true,false,'EXCLUIR');raise exception 'FAIL secretary bypasses active acknowledgement';exception when raise_exception then if sqlerrm like 'FAIL%' then raise;end if;end;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',pu,'role','authenticated','aal','aal1')::text,true);
 begin perform public.crm_delete_client(pp,'QA deletion patient',true,true,'EXCLUIR');raise exception 'FAIL patient can delete';exception when insufficient_privilege then null;end;
 if exists(select 1 from public.client_deletion_jobs) then raise exception 'FAIL deletion jobs exposed to patient';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',au,'role','authenticated','aal','aal1')::text,true);
 job:=public.crm_delete_client(pp,'QA deletion patient',true,true,'EXCLUIR');
 if exists(select 1 from public.profiles where id=pp) or exists(select 1 from public.crm_enrollments where patient_id=pp) or exists(select 1 from public.crm_contacts where enrollment_id=e) or exists(select 1 from public.clinical_records where patient_id=pp) or exists(select 1 from public.clinical_change_history where patient_id=pp) or exists(select 1 from public.patient_water_logs where patient_id=pp) or exists(select 1 from public.care_tasks where patient_id=pp) then raise exception 'FAIL patient data retained';end if;
 if not exists(select 1 from public.client_deletion_jobs where id=job and user_id=pu) then raise exception 'FAIL auth cleanup job';end if;
 if not exists(select 1 from public.profiles where id=ap) or not exists(select 1 from public.profiles where id=sp) then raise exception 'FAIL another client/team affected';end if;
 execute 'reset role';
 if (select banned_until from auth.users where id=pu)<=now() then raise exception 'FAIL access not blocked';end if;
end $$;
select 'PASS client deletion: explicit confirmation, active period acknowledgement for all staff, patient denied, dependent data removed, access blocked, private cleanup job, team preserved' as result;
rollback;
